// ============================================================
// NORMALIZE INPUT
// Unifies all three trigger formats into one standard schema:
// { source, text, chat_id, trigger_type, intent, params }
// ============================================================

const input = $input.first().json;

let source, text, chat_id, trigger_type, intent, params;

if (input.message) {
  // --- Telegram trigger ---
  source = 'telegram';
  trigger_type = 'telegram';
  text = (input.message.text || '').trim();
  chat_id = input.message.chat?.id;
  intent = null; // Brian will classify
  params = {};

} else if ('timestamp' in input || 'scheduleTime' in input || input._source === 'schedule') {
  // --- Schedule trigger ---
  source = 'schedule';
  trigger_type = 'schedule';
  text = 'scheduled digest';
  chat_id = null; // Will be loaded from preferences in context step
  intent = 'find_jobs';
  params = { digest: true, top_n: 5 };

} else {
  // --- Manual trigger ---
  source = 'manual';
  trigger_type = 'manual';
  text = input.text || '';
  chat_id = input.chat_id || null;
  intent = input.intent || 'find_jobs';
  params = input.params || {};
}

return [{ json: { source, text, chat_id, trigger_type, intent, params } }];

const data = $input.first().json;
const normalized = $('Normalize Input').first().json;
const locPref = $('Load Location Pref').first().json;
const recentJobs = $('Load Recent Jobs').first().json;
const resumeResp = $('Load Resume').first().json;

const location = (locPref?.value || locPref?.location || 'New York');
const context = {
  location,
  visa_required: locPref?.visa_required || false,
  salary_min: locPref?.salary_min || null,
};
const recent_jobs = recentJobs?.jobs || recentJobs?.documents || [];
const resume_text = resumeResp?.resume_text || 'No resume loaded. Place your resume in storage/master_resume/master_resume.txt';

return [{
  json: {
    ...normalized,
    context,
    location_override: normalized.location_override || null,
    recent_jobs,
    resume_text
  }
}];

// ============================================================
// BRIAN ROUTER
// Classifies intent for Telegram messages only.
// Schedule + Manual triggers already have intent set.
// ============================================================

const data = $input.first().json;

// Pass through if intent already set (schedule / manual)
if (data.intent) {
  return [{ json: data }];
}

const text = (data.text || '').toLowerCase().trim();
let intent = 'help';
let location_override = null;
let company = null;
let job_number = null;
let pref_key = null;
let pref_value = null;

// --- Intent classification (regex-based, replace with LLM call in Sprint 5) ---

if (/\bfind\b|\bsearch\b|\bjobs\b|\bdigest\b|\blatest\b|\bshow me jobs\b|\bjob list\b|\brecent jobs\b/.test(text)) {
  intent = 'find_jobs';
  const locMatch = text.match(/\b(?:in|near|around)\s+([a-zA-Z][a-zA-Z\s,]{2,30})(?:\s|,|$)/i);
  if (locMatch) location_override = locMatch[1].trim();
  if (/\bremote\b/.test(text)) location_override = 'Remote';

} else if (/\bapply\b|\bgenerate resume\b|\bcreate resume\b|\bresume for\b/.test(text) || /^\d+$/.test(text)) {
  intent = 'apply';
  const numMatch = text.match(/\d+/);
  if (numMatch) job_number = parseInt(numMatch[0]);

} else if (/\bintel\b|\bresearch\b|\btell me about\b|\bcompany profile\b|\bwhat is\b/.test(text)) {
  intent = 'intel';
  const co = text.match(/(?:about|research|intel(?:\s+on)?|tell me about|profile of)\s+([A-Za-z][A-Za-z0-9\s&.-]{1,40})(?:\s|$)/i);
  if (co) company = co[1].trim();

} else if (/\binterview\b|\bprep\b|\bpractice\b|\bquestions\b|\binterview prep\b/.test(text)) {
  intent = 'interview_prep';
  const co = text.match(/(?:for|at|with)\s+([A-Za-z][A-Za-z0-9\s]{1,30})(?:\s|$)/i);
  if (co) company = co[1].trim();

} else if (/\bsalary\b|\bnegotiat\b|\bcounter offer\b|\bcomp\b|\bcompensation\b|\blevels\b/.test(text)) {
  intent = 'salary_coach';

} else if (/\bset\b|\bupdate\b|\bchange\b|\bmy location\b|\bi need visa\b|\bh-?1b\b|\bsponsor\b|\bprefer\b/.test(text)) {
  intent = 'set_preference';
  const locSet = text.match(/(?:location|city|based in|move to|relocat)\s+(?:to|is|=|:)?\s*([A-Za-z][A-Za-z\s,]{2,30})(?:\s|,|$)/i);
  if (locSet) { pref_key = 'location'; pref_value = locSet[1].trim(); }
  const salSet = text.match(/salary(?:\s+min(?:imum)?)?\s*(?:to|is|=|:)?\s*(\$?[\d,]+)/i);
  if (salSet) { pref_key = 'salary_min'; pref_value = salSet[1].replace(/[$,]/g, ''); }
  if (/\bvisa\b|\bh-?1b\b|\bsponsor/.test(text) && !pref_key) { pref_key = 'visa_required'; pref_value = 'true'; }

} else if (/\btracker\b|\bapplication\b|\bstatus\b|\bapplied\b|\bhistory\b|\bmy applications\b/.test(text)) {
  intent = 'tracker';
} else if (/\bcreate\b|\bmaster resume\b|\bbuild resume\b|\bonboard\b/.test(text)) {
  intent = 'create_resume';
}

return [{ json: { ...data, intent, location_override, company, job_number, pref_key, pref_value } }];

// Sprint 3: Pass through context so the HTTP Request node can read it.
// n8n is front door — it sends the ack, then calls avatar service.
const data = $input.first().json;
const jobNum = data.job_number;
const msg = jobNum
  ? `⚙️ *CareerForge Apply — job #${jobNum}*\n\nOn it! Rita is researching the role and Ryan is tailoring your resume. Give me ~30 seconds...`
