const ctx = $('Merge Context').first().json;
const location = ctx.location_override || ctx.context?.location || 'New York';
const chatId = ctx.chat_id;
const isDig = ctx.params?.digest || false;
const resumeText = "YOUR FULL NAME | your.email@example.com | Your City, State | yoursite.com | Work Authorization Status\n\nYour Company (Mar 2025-Mar 2026): fMRI 89% accuracy PyTorch stDNN 4 cohorts. RAG Neurosynth 31% faster 19% better QA. DeepSeek R1 671B to LLaMA 3.2 3B 85% cost reduction GPTQ/AWQ. Multi-LLM OpenRouter.\n\nYour Company (Nov 2024-Feb 2025): Oracle PL/SQL 20% faster. Prometheus/Grafana 45% fewer outages. AWS Lambda CloudWatch.\n\nYour Company (Feb 2024-Nov 2024): Airflow AWS EC2 40% less manual effort. 1M+ SQL/Pandas. Looker Studio.\n\nYour Company (Apr 2020-Jul 2022): C++/CATIA 20% fewer crashes. Python CADAM test automation 87% faster 35% more coverage.\n\nDeloitte (Apr 2026-present): Senior GenAI Engineer, multi-agent systems.\n\nCareerForge: 5-workflow n8n multi-agent platform demoed n8n NYC Apr 2026. PrometheusAI: 8-agent system 21x relevance. Speaker LLM Day NYC Mar 2026. 1st Place Pulse NYC Jan 2026.";

let queries = [], skills = [], roles = [];
try {
  const raw = (r?.choices?.[0]?.message?.content || '{}').replace(/```json\n?/g,'').replace(/```\n?/g,'').trim();
  const p = JSON.parse(raw);
  queries = p.ats_queries || [];
  skills = p.skills || [];
  roles = p.role_titles || [];
} catch(e) {
  // Fallback queries based on resume
  queries = [
    {q:'AI Engineer LLM RAG '+location+' site:job-boards.greenhouse.io', label:'Greenhouse'},
    {q:'Machine Learning Engineer PyTorch '+location+' site:jobs.ashbyhq.com', label:'Ashby'},
    {q:'AI Engineer multi-agent systems '+location+' site:lever.co/jobs', label:'Lever'}
  ];
  skills = ['PyTorch','RAG','LLM','Python','AWS','n8n'];
  roles = ['AI Engineer','Machine Learning Engineer','Senior GenAI Engineer'];
}

return [{ json: { queries, skills, roles, chat_id: chatId, location, is_digest: isDig, resume_text: resumeText } }];

const { queries, skills, roles, chat_id, location, is_digest, resume_text } = $json;

const serperKey = $json.serper_key;
const allUrls = new Map(); // url -> {title, link, snippet, label}

await Promise.all(queries.map(async qObj => {
  try {
    const resp = await fetch('https://google.serper.dev/search', {
      method: 'POST',
      headers: { 'X-API-KEY': serperKey, 'Content-Type': 'application/json' },
      body: JSON.stringify({ q: qObj.q, gl: 'us', num: 10 }),
      signal: AbortSignal.timeout(10000)
    });
    const data = await resp.json();
    (data.organic || []).forEach(item => {
      if (!allUrls.has(item.link)) {
        allUrls.set(item.link, {
          title: item.title,
          url: item.link,
          snippet: item.snippet || '',
          source: qObj.label
        });
      }
    });
  } catch(e) { console.log('Serper query failed:', qObj.label, e.message); }
}));

const candidates = Array.from(allUrls.values());
console.log('Serper found', candidates.length, 'unique job URLs across', queries.length, 'queries');
return [{ json: { candidates, skills, roles, chat_id, location, is_digest, resume_text , fc_key: $json.fc_key, or_key: $json.or_key } }];

