      headers: { 'Authorization': 'Bearer ' + fcKey, 'Content-Type': 'application/json' },
      body: JSON.stringify({ url: c.url, formats: ['markdown'], timeout: 15000 }),
      signal: AbortSignal.timeout(20000)
    });
    const data = await resp.json();
    if (!data.success || !data.data?.markdown) return null;
    const md = data.data.markdown;
    // Check if job is still active -- drop if expired
    const expired = /no longer accepting|position (has been )?filled|job (has )?closed|this role (has )?been filled/i.test(md);
    if (expired) return null;
    // Extract title + company from markdown or fallback to snippet title
    const titleMatch = md.match(/^#+ (.+)/m);
    const title = titleMatch ? titleMatch[1].trim() : c.title.replace(/^Job Application for /i,'').replace(/ - Jobs$/i,'').trim();
    const compMatch = md.match(/\*\*Company\*\*:? ?(.+)|^## (.+)/m);
    const company = compMatch ? (compMatch[1]||compMatch[2]).trim() : c.source;
    return { title, company, url: c.url, jd_text: md.slice(0, 3000), source: c.source };
  } catch(e) { return null; }
}));

const verified = scraped.filter(Boolean);
console.log('Firecrawl verified', verified.length, '/', toScrape.length, 'jobs');
return [{ json: { verified, skills, roles, chat_id, location, is_digest, resume_text } }];

