const scoreResp = $input.first().json;
const prevData = $('FJ: Firecrawl Scrape').first().json;
const { verified, chat_id, location, is_digest } = prevData;

let scores = [];
try {
  const raw = (scoreResp?.choices?.[0]?.message?.content||'{}').replace(/```json\n?/g,'').replace(/```\n?/g,'').trim();
  scores = JSON.parse(raw).scores || [];
} catch(e) { scores = verified.map((_,i)=>({idx:i,score:5,reason:'',visa:false,location:''})); }

const scored = scores
  .filter(s => s.score >= 6)
  .map(s => ({
    ...verified[s.idx],
    forge_score: s.score,
    forge_reason: s.reason,
    visa: s.visa,
    scored_location: s.location
  }))
  .sort((a,b) => b.forge_score - a.forge_score)
  .slice(0, is_digest ? 5 : 10);

if (scored.length === 0) {
  return [{ json: {
    chat_id, jobs: [],
    message: '🔍 No strong matches found this search. Try rephrasing or searching again for a fresh batch!'
  }}];
}

const header = is_digest
  ? `📅 *Morning Digest* — ${new Date().toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric'})}`
  : `🎯 *Job Results* — ${scored.length} matches (AI-scored for your profile)`;

const lines = scored.map((j,i) =>
  `${i+1}\. *${j.title}* @ ${j.company}\n   📍 ${j.scored_location || location}  |  🎯 Score: ${j.forge_score}/10\n   🔗 ${j.url}`
);
return [{ json: {
  chat_id,
  message: `${header}\n\n${lines.join('\n\n')}\n\n💡 Reply with a number to generate your tailored resume + cover letter.`,
  jobs: scored
}}];
